import type { DocNetProject, DocNetProjectCreate } from 'src/@types/docnet';
import DocNetBaseService from 'src/services/docnet/DocNetBaseService';
import { api } from 'src/pages/APIs';

export default class DocNetProjectService extends DocNetBaseService {
  public async getProjects(): Promise<DocNetProject[]> {
    const headers = await this.getHeaders();
    const response = await super.get(api.docnet_projects, { headers });
    const items = (response as any).items;
    return Array.isArray(items) ? items : Array.isArray(response) ? (response as DocNetProject[]) : [];
  }

  public async getProjectById(
    id: string,
  ): Promise<DocNetProject | undefined> {
    const headers = await this.getHeaders();
    try {
      return (await super.get(`${api.docnet_projects}/${id}`, {
        headers,
      })) as DocNetProject;
    } catch {
      return undefined;
    }
  }

  public async createProject(
    data: DocNetProjectCreate,
  ): Promise<DocNetProject> {
    const headers = await this.getHeaders();
    return (await super.post(api.docnet_projects, data, {
      headers,
    })) as DocNetProject;
  }

  public async updateProject(
    id: string,
    data: Partial<DocNetProject>,
  ): Promise<DocNetProject> {
    const headers = await this.getHeaders();
    return (await super.patch(`${api.docnet_projects}/${id}`, data, {
      headers,
    })) as DocNetProject;
  }

  public async deleteProject(id: string): Promise<void> {
    const headers = await this.getHeaders();
    await super.delete(`${api.docnet_projects}/${id}`, { headers });
  }
}
