import { defineStore } from 'pinia';
import DocNetProjectService from 'src/services/docnet/DocNetProjectService';
import { useDocNetSettingsStore } from './docnet-settings.store';
import type {
  DocNetProject,
  DocNetProjectCreate,
} from 'src/@types/docnet';

const projectService = new DocNetProjectService();

export const useDocNetProjectStore = defineStore('docnet_projects', {
  state: () => ({
    projects: [] as DocNetProject[],
    currentProject: null as DocNetProject | null,
    loading: false,
  }),

  getters: {
    activeProjects(state): DocNetProject[] {
      return state.projects.filter((p) => p.status === 'active');
    },

    projectSelectOptions(state): { label: string; value: string }[] {
      return state.projects.map((p) => ({
        label: p.name,
        value: p.id,
      }));
    },
  },

  actions: {
    async fetchProjects(): Promise<void> {
      const settings = useDocNetSettingsStore();
      if (settings.useMockData) {
        const { mockProjects } = await import('src/mocks/docnet/projects');
        this.projects = mockProjects;
        return;
      }
      this.loading = true;
      try {
        this.projects = await projectService.getProjects();
      } catch (error) {
        console.error('[DocNet] Failed to fetch projects:', error);
        throw error;
      } finally {
        this.loading = false;
      }
    },

    async fetchProject(id: string): Promise<void> {
      const settings = useDocNetSettingsStore();
      if (settings.useMockData) {
        const { mockProjects } = await import('src/mocks/docnet/projects');
        this.currentProject = mockProjects.find(p => p.id === id) ?? null;
        return;
      }
      this.loading = true;
      try {
        const project = await projectService.getProjectById(id);
        this.currentProject = project ?? null;
        if (project) {
          const index = this.projects.findIndex((p) => p.id === id);
          if (index !== -1) {
            this.projects[index] = project;
          }
        }
      } catch (error) {
        console.error('[DocNet] Failed to fetch project:', error);
        throw error;
      } finally {
        this.loading = false;
      }
    },

    async createProject(data: DocNetProjectCreate): Promise<DocNetProject> {
      this.loading = true;
      try {
        const project = await projectService.createProject(data);
        this.projects.push(project);
        return project;
      } catch (error) {
        console.error('[DocNet] Failed to create project:', error);
        throw error;
      } finally {
        this.loading = false;
      }
    },

    async deleteProject(id: string): Promise<void> {
      try {
        await projectService.deleteProject(id);
        this.projects = this.projects.filter((p) => p.id !== id);
        if (this.currentProject?.id === id) {
          this.currentProject = null;
        }
      } catch (error) {
        console.error('[DocNet] Failed to delete project:', error);
        throw error;
      }
    },

    async updateProject(
      id: string,
      data: Partial<DocNetProject>,
    ): Promise<DocNetProject> {
      this.loading = true;
      try {
        const updated = await projectService.updateProject(id, data);
        const index = this.projects.findIndex((p) => p.id === id);
        if (index !== -1) {
          this.projects[index] = updated;
        }
        if (this.currentProject?.id === id) {
          this.currentProject = updated;
        }
        return updated;
      } catch (error) {
        console.error('[DocNet] Failed to update project:', error);
        throw error;
      } finally {
        this.loading = false;
      }
    },
  },
});
